#define CMAP_COUNT (sizeof(cmap_entries) / sizeof(cmap_entries[0]))

const uint8_t *embedded_collision_map(const char *path, size_t *out_size) {
    for (size_t i = 0; i < CMAP_COUNT; i++) {
        if (strcmp(path, cmap_entries[i].path) == 0) {
            *out_size = cmap_entries[i].size;
            return cmap_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
